import { faker } from '@faker-js/faker'
import { Avatar, Box, IconButton, Stack, Typography } from '@mui/material'
import React from 'react'
import StyledBadge from './StyledBadge'
import { ArrowDownLeft, ArrowUpRight, Phone, VideoCamera } from 'phosphor-react'

const CallLogElement = ({ online, incoming, missed }) => {

    return (
        <Box
            sx={{
                borderRadius: 1,
                backgroundColor: (theme) => theme.palette.mode === "light" ? "#fff" : theme.palette.background.paper
            }}
            p={2}
        >
            <Stack
                direction='row'
                alignItems={'center'}
                justifyContent='space-between'
            >
                <Stack direction={'row'} alignItems={'center'} spacing={2}>
                    {online ?
                        (
                            <StyledBadge overlap="circular" anchorOrigin={{ vertical: "bottom", horizontal: "right" }} variant="dot">
                                <Avatar src={faker.image.avatar()} alt={faker.person.fullName} />
                            </StyledBadge>
                        ) : (<Avatar src={faker.image.avatar()} alt={faker.person.fullName} />)
                    }

                    <Stack spacing={0.3}>
                        <Typography variant='subtitle2'>{faker.person.fullName()}</Typography>
                        {/* <Typography variant='caption'>{truncateText(msg, 20)}</Typography> */}
                        <Stack direction={'row'} alignItems={'center'} spacing={1}>
                            {incoming ? <ArrowDownLeft color={missed ? 'red' : 'green'} /> : <ArrowUpRight color={missed ? 'red' : 'green'} />}
                            <Typography variant='caption'>Yesterday 21:24</Typography>
                        </Stack>
                    </Stack>
                </Stack>
                <IconButton>
                    <Phone color='green' size={20} />
                </IconButton>
            </Stack>
        </Box>
    )
}

const CallElement = ({ id,img,name,online }) => {
    return (
        <Box
            sx={{
                borderRadius: 1,
                backgroundColor: (theme) => theme.palette.mode === "light" ? "#fff" : theme.palette.background.paper
            }}
            p={2}
        >
            <Stack
                direction='row'
                alignItems={'center'}
                justifyContent='space-between'
            >
                <Stack direction={'row'} alignItems={'center'} spacing={2}>
                    {online ?
                        (
                            <StyledBadge overlap="circular" anchorOrigin={{ vertical: "bottom", horizontal: "right" }} variant="dot">
                                <Avatar src={img} alt={name} />
                            </StyledBadge>
                        ) : (<Avatar src={img} alt={name} />)
                    }

                    <Stack spacing={0.3}>
                        <Typography variant='subtitle2'>{name}</Typography>
                        {/* <Typography variant='caption'>{truncateText(msg, 20)}</Typography> */}
                    </Stack>
                </Stack>
                <Stack direction={'row'} alignItems={'center'} >
                    <IconButton>
                        <Phone color='green' size={22} />
                    </IconButton>
                    <IconButton>
                        <VideoCamera color='green' size={22} />
                    </IconButton>
                </Stack>
            </Stack>
        </Box>
    )
}

export { CallElement, CallLogElement };